import mongoose, { Schema } from 'mongoose';
const objectId = Schema.Types.ObjectId;
const userSchema = new Schema({ email: { type: String, required: true, unique: true, lowercase: true, trim: true }, passwordHash: { type: String, required: true }, name: { type: String, required: true }, roles: { type: [String], default: ['user'] }, notificationPreferences: { email: { type: Boolean, default: true }, inApp: { type: Boolean, default: true } } }, { timestamps: true });
const profileSchema = new Schema({ userId: { type: objectId, required: true, ref: 'User', index: true }, name: { type: String, required: true }, locations: [{ city: String, districts: [String] }], radiusKm: { type: Number, min: 0, max: 200 }, rent: { coldMin: Number, coldMax: Number, warmMin: Number, warmMax: Number }, rooms: { min: Number, max: Number }, area: { min: Number, max: Number }, propertyTypes: [String], features: [String], availableFrom: Date, documentIds: [{ type: objectId, ref: 'Document' }], active: { type: Boolean, default: true } }, { timestamps: true });
const listingSchema = new Schema({ source: { type: String, required: true }, externalId: { type: String, required: true }, canonicalUrl: String, title: String, city: String, district: String, postalCode: String, address: String, coldRent: Number, warmRent: Number, rooms: Number, areaSqm: Number, propertyType: String, features: [String], availableFrom: Date, fingerprint: String, firstSeenAt: { type: Date, default: Date.now }, lastSeenAt: { type: Date, default: Date.now }, isActive: { type: Boolean, default: true } }, { timestamps: true });
listingSchema.index({ source: 1, externalId: 1 }, { unique: true });
listingSchema.index({ fingerprint: 1 }, { unique: true, sparse: true });
const documentSchema = new Schema({ userId: { type: objectId, required: true, ref: 'User', index: true }, profileIds: [{ type: objectId, ref: 'Profile' }], kind: { type: String, enum: ['income', 'credit_report', 'identity', 'self_disclosure', 'other'], required: true }, originalName: String, objectKey: { type: String, required: true }, encryptedDek: { type: String, required: true }, iv: { type: String, required: true }, authTag: { type: String, required: true }, mimeType: { type: String, required: true }, size: { type: Number, required: true }, status: { type: String, enum: ['pending_scan', 'clean', 'rejected'], default: 'pending_scan' } }, { timestamps: true });
const matchSchema = new Schema({ userId: { type: objectId, required: true, ref: 'User', index: true }, profileId: { type: objectId, required: true, ref: 'Profile' }, listingId: { type: objectId, required: true, ref: 'Listing' }, score: Number, reasons: [String], status: { type: String, enum: ['new', 'saved', 'dismissed', 'applied'], default: 'new' }, notifiedAt: Date }, { timestamps: true });
matchSchema.index({ profileId: 1, listingId: 1 }, { unique: true });
export const User = mongoose.model('User', userSchema);
export const Profile = mongoose.model('Profile', profileSchema);
export const Listing = mongoose.model('Listing', listingSchema);
export const Document = mongoose.model('Document', documentSchema);
export const Match = mongoose.model('Match', matchSchema);
